export const bondPricingDefinitions={
  bondPricingPlanning:{title:'Reprice one invented annual-pay bond and track its first coupon',fields:[
    ['pricingFace','Principal promised at maturity (CAD)',1000,100,100000,100],
    ['pricingCoupon','Annual coupon rate on face value (%)',5,0,15,.25],
    ['pricingYield','Annual required yield at purchase (%)',5,0,15,.25],
    ['pricingExitYield','Required yield after the hypothetical change (%)',7,0,15,.25],
    ['pricingYears','Whole years to the final payment at purchase',10,1,30,1]
  ]}
};
export function annualBondCashflows(face,coupon,years){
  return Array.from({length:years},(_,i)=>({year:i+1,coupon:face*coupon/100,principal:i+1===years?face:0,value:face*coupon/100+(i+1===years?face:0)}));
}
export function annualBondPrice(face,coupon,yieldRate,years){
  return annualBondCashflows(face,coupon,years).reduce((n,r)=>n+r.value/(1+yieldRate/100)**r.year,0);
}
export function annualBondDuration(face,coupon,yieldRate,years){
  const rows=annualBondCashflows(face,coupon,years),price=annualBondPrice(face,coupon,yieldRate,years),macaulay=rows.reduce((n,r)=>n+r.year*r.value/(1+yieldRate/100)**r.year,0)/price;
  return {macaulay,modified:macaulay/(1+yieldRate/100)};
}
export function bondPricingSnapshot(input){
  const price=annualBondPrice(input.pricingFace,input.pricingCoupon,input.pricingYield,input.pricingYears),duration=annualBondDuration(input.pricingFace,input.pricingCoupon,input.pricingYield,input.pricingYears),repriced=annualBondPrice(input.pricingFace,input.pricingCoupon,input.pricingExitYield,input.pricingYears),linearPrice=price*(1-duration.modified*(input.pricingExitYield-input.pricingYield)/100),couponCash=input.pricingFace*input.pricingCoupon/100,saleValue=input.pricingYears>1?annualBondPrice(input.pricingFace,input.pricingCoupon,input.pricingExitYield,input.pricingYears-1):0,redemption=input.pricingYears===1?input.pricingFace:0,exitValue=saleValue+redemption,cashAfterOneYear=couponCash+exitValue;
  return {price,...duration,repriced,linearPrice,couponCash,saleValue,redemption,exitValue,cashAfterOneYear,oneYearReturn:cashAfterOneYear/price-1};
}
export function bondPricingResult(kind,input){
  if(kind!=='bondPricingPlanning')throw Error('Unknown bond-pricing topic.');
  const p=bondPricingSnapshot(input),yields=Array.from({length:61},(_,i)=>i/4),cashflows=annualBondCashflows(input.pricingFace,input.pricingCoupon,input.pricingYears),coupons=[...new Set([0,3,5,8,input.pricingCoupon])].sort((a,b)=>a-b);
  return {metrics:[['Purchase price from all promised annual cash flows',p.price,'money'],['Immediate price at the changed required yield',p.repriced,'money'],['One-year coupon plus sale / redemption total return',p.oneYearReturn,'percent']],note:'One invented noncallable, option-free fixed-rate annual-pay bond, priced immediately after a coupon date with exactly the entered whole years remaining. Coupon and required yields use annual compounding. All promised cash flows are assumed paid in full and on time; no default or recovery is simulated. The first price comparison reprices instantly before any payment. The separate one-year calculation receives one coupon and sells immediately after that coupon at the entered exit yield; a one-year bond instead repays principal then. There is no coupon reinvestment within this single period. No accrued interest, tax, commissions, spread, currency, inflation, embedded option, yield-curve shape or future trades are included. Rates and prices are assumptions, not market observations or bond-fund forecasts. Macaulay duration is '+p.macaulay.toFixed(4)+' years and modified duration is '+p.modified.toFixed(4)+' under this annual convention.',charts:[
    {id:'bond-pricing-promised-payments',type:'stackbar',title:'Identify the promised coupon and principal cash flows first',unit:'money',unitLabel:'CAD promised at each annual payment date; not market value',seriesNames:['Annual coupon','Principal at final payment'],rows:cashflows.map(r=>({label:'End of year '+r.year,values:[r.coupon,r.principal]})),note:'The coupon is face value × coupon rate, paid once at each year-end in this invented annual-pay bond. Principal is paid once at the final date. All annual dates are included, even when the chart is long. Promised cash flows are distinct from today’s purchase price. No actual issuer or guarantee is represented.'},
    {id:'bond-pricing-yield-curve',type:'line',title:'Compare discounted cash-flow prices with a linear duration estimate',unit:'money',unitLabel:'Immediate price in CAD; every point uses the original payment dates',xLabel:'Required annual yield (%)',xTicks:[0,5,10,15].map(value=>({value,label:value+'%'})),series:[{name:'Price by discounting every promised cash flow',rows:yields.map(x=>({x,label:x+'%',value:annualBondPrice(input.pricingFace,input.pricingCoupon,x,input.pricingYears)}))},{name:'Linear estimate from purchase-date modified duration',dash:true,rows:yields.map(x=>({x,label:x+'%',value:p.price*(1-p.modified*(x-input.pricingYield)/100)}))}],note:'Each point is an independent instantaneous repricing, before the first coupon; time to maturity does not shorten along this horizontal axis. The selected changed-yield price is CAD '+p.repriced.toFixed(2)+'; its first-order estimate is CAD '+p.linearPrice.toFixed(2)+'. The straight line uses price × [1 − modified duration × yield change in decimal form]. It is a local approximation and becomes less accurate for large moves. If it turns negative, that is failure of the approximation, not a valid negative bond price. The discounted promised-cash-flow price remains positive.'},
    {id:'bond-pricing-coupon-maturity-grid',type:'heatmap',signed:true,title:'Test how coupon and maturity change the same immediate yield sensitivity',unit:'percent',unitLabel:'Exact instantaneous price change; columns replace initial years to final payment',columns:['1 yr','5 yrs','10 yrs','30 yrs'],rows:[0,3,5,8].map(coupon=>({label:coupon+'% coupon',values:[1,5,10,30].map(years=>annualBondPrice(input.pricingFace,coupon,input.pricingExitYield,years)/annualBondPrice(input.pricingFace,coupon,input.pricingYield,years)-1)})),note:'Every cell compares prices before and after the entered yield change, using the same face value and its stated coupon/maturity. Rows replace the coupon control; columns replace the maturity control. The matrix is not a year-by-year holding path or a probability estimate. It excludes coupon receipts because the repricing is instantaneous. A zero yield change gives zero price change in every cell; the sign reverses when the entered yield falls. Cell labels are rounded to one decimal place; the data table retains two.'},
    {id:'bond-pricing-one-year-cash',type:'waterfall',title:'Add the first coupon to the correctly aged sale or redemption value',unit:'money',unitLabel:'CAD at the end of the separate one-year holding period',rows:[{label:'Original purchase price',value:p.price},{label:input.pricingYears===1?'Redemption value minus purchase price':'Sale value minus purchase price',value:p.exitValue-p.price},{label:'First annual coupon received as cash',value:p.couponCash}],totalLabel:'Coupon plus sale / redemption cash',note:'At the default ten-year maturity, the year-one sale prices nine remaining annual payments at the entered exit yield. It does not reuse the ten-year immediate-repricing price. The waterfall ends at CAD '+p.cashAfterOneYear.toFixed(2)+', compared with original purchase cost CAD '+p.price.toFixed(2)+'. The coupon is added once; remaining principal is already inside the sale value. When only one year remains at purchase, the principal is redeemed at year-end and the exit-yield input cannot change that assumed contractual receipt. No coupon is reinvested or counted in both the sale price and cash.'},
    {id:'bond-pricing-duration-maturity',type:'groupbar',title:'Distinguish the final payment year from the two duration measures',unit:'decimal',tableUnit:'years',unitLabel:'Years under the annual coupon / annual yield convention',seriesNames:['Macaulay duration','Modified duration','Final payment year'],rows:coupons.map(coupon=>{const d=annualBondDuration(input.pricingFace,coupon,input.pricingYield,input.pricingYears);return {label:coupon+'% coupon'+(coupon===input.pricingCoupon?' · selected coupon':''),values:[d.macaulay,d.modified,input.pricingYears]};}),note:'Each row is a separate hypothetical coupon at the selected initial maturity and purchase yield. Macaulay duration weights payment dates by each cash flow’s present value; modified duration divides that result by 1 + annual yield. For a zero-coupon bond, Macaulay duration equals its final payment year, while modified duration differs when yield is positive. Neither modified duration nor a bond fund’s duration is a promise that an interim loss will recover after that many years. The exit-yield control does not change these purchase-date measures.'}
  ]};
}
